package com.andye.warmod.radar.network;
import com.andye.warmod.WarMod;import com.andye.warmod.radar.*;import java.util.List;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.network.codec.StreamCodec;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;import net.minecraft.resources.Identifier;
public record ClientboundRadarSnapshotPayload(Identifier dimensionId,long serverGameTime,List<RadarTrackSnapshot> tracks,List<RadarImpactSnapshot> impacts) implements CustomPacketPayload{public static final Type<ClientboundRadarSnapshotPayload> TYPE=new Type<>(Identifier.fromNamespaceAndPath(WarMod.MOD_ID,"radar_snapshot"));public static final StreamCodec<RegistryFriendlyByteBuf,ClientboundRadarSnapshotPayload> STREAM_CODEC=StreamCodec.of((b,p)->{b.writeIdentifier(p.dimensionId);b.writeLong(p.serverGameTime);RadarNetworkCodecs.writeTracks(b,p.tracks);RadarNetworkCodecs.writeImpacts(b,p.impacts);},b->new ClientboundRadarSnapshotPayload(b.readIdentifier(),b.readLong(),RadarNetworkCodecs.readTracks(b),RadarNetworkCodecs.readImpacts(b)));public ClientboundRadarSnapshotPayload{tracks=List.copyOf(tracks);impacts=List.copyOf(impacts);}@Override public Type<? extends CustomPacketPayload> type(){return TYPE;}}
